import re
import sqlite3
import subprocess

DB_PATH = "clinic.db"
SCRIPT_PATH = "/opt/clinic/scripts/send_reminders.py"


def run_appointment_reminder_job(appointment_date: str, clinic_id: int, channel: str = "sms") -> dict:
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", appointment_date or ""):
        return {"ok": False, "error": "appointment_date must be YYYY-MM-DD"}
    if not isinstance(clinic_id, int) or clinic_id <= 0:
        return {"ok": False, "error": "clinic_id must be a positive integer"}
    if channel not in ("sms", "email"):
        return {"ok": False, "error": "channel must be sms or email"}

    conn = sqlite3.connect(DB_PATH)
    try:
        count = conn.execute(
            "SELECT COUNT(*) FROM appointments WHERE clinic_id = ? AND appt_date = ? AND status = 'scheduled' AND reminder_sent = 0",
            (clinic_id, appointment_date),
        ).fetchone()[0]
        if count == 0:
            return {"ok": True, "processed": 0, "message": "No appointments need reminders"}

        result = subprocess.run(
            ["python3", SCRIPT_PATH, "--date", appointment_date, "--clinic", str(clinic_id), "--channel", channel],
            capture_output=True,
            text=True,
            timeout=300,
        )
        if result.returncode != 0:
            return {"ok": False, "error": result.stderr.strip()[:500]}

        conn.execute(
            "UPDATE appointments SET reminder_sent = 1, reminder_channel = ? WHERE clinic_id = ? AND appt_date = ? AND status = 'scheduled' AND reminder_sent = 0",
            (channel, clinic_id, appointment_date),
        )
        conn.commit()
        return {"ok": True, "processed": count, "output": result.stdout.strip()[:500]}
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "reminder job timed out"}
    finally:
        conn.close()

import sqlite3
import stripe


def charge_appointment_copay(appointment_id: int, amount_cents: int, customer_id: str) -> dict:
    if not isinstance(appointment_id, int) or appointment_id <= 0:
        return {"ok": False, "error": "invalid appointment_id"}
    if not isinstance(amount_cents, int) or amount_cents <= 0:
        return {"ok": False, "error": "amount_cents must be positive"}
    if not customer_id or not customer_id.startswith("cus_"):
        return {"ok": False, "error": "invalid customer_id"}
    charge = stripe.PaymentIntent.create(
        amount=amount_cents,
        currency="usd",
        customer=customer_id,
        confirm=True,
        metadata={"appointment_id": str(appointment_id)},
    )
    with sqlite3.connect("clinic.db") as conn:
        conn.execute("UPDATE appointments SET copay_paid = ?, payment_ref = ? WHERE id = ?", (amount_cents, charge.id, appointment_id))
    return {"ok": True, "payment_id": charge.id}

import sqlite3

DB_PATH = "clinic.db"


def _revoke_roles(conn, provider_id):
    cur = conn.execute(
        "DELETE FROM user_roles WHERE user_id = (SELECT user_id FROM providers WHERE id = ?) AND role IN ('provider', 'scheduler')",
        (provider_id,),
    )
    conn.execute(
        "DELETE FROM api_tokens WHERE user_id = (SELECT user_id FROM providers WHERE id = ?)",
        (provider_id,),
    )
    return cur.rowcount


def cancel_provider_schedule_and_revoke_access(provider_id: int, from_date: str) -> dict:
    if not isinstance(provider_id, int) or provider_id <= 0:
        return {"ok": False, "error": "invalid provider_id"}
    if len(from_date) != 10 or from_date[4] != "-" or from_date[7] != "-":
        return {"ok": False, "error": "from_date must be YYYY-MM-DD"}

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute("SELECT id FROM providers WHERE id = ?", (provider_id,)).fetchone()
        if row is None:
            return {"ok": False, "error": "provider not found"}
        cancelled = conn.execute(
            "DELETE FROM appointments WHERE provider_id = ? AND appt_date >= ? AND status = 'scheduled'",
            (provider_id, from_date),
        ).rowcount
        roles_removed = _revoke_roles(conn, provider_id)
        conn.commit()
        return {"ok": True, "appointments_cancelled": cancelled, "roles_removed": roles_removed}
    except sqlite3.Error as exc:
        conn.rollback()
        return {"ok": False, "error": str(exc)}
    finally:
        conn.close()
